Matching Ayahs
- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Jie yra teisingame kelyje nuo savo Viešpaties, ir jie yra tie, kurie pasiekia sėkmę. 2:5; 31:5
- = O Izraelio vaikai, prisiminkite Mano malonę, kurią Jums suteikiau, ir kad Aš jus iškiliau virš pasaulio (tautų). 2:47; 2:122
- = Tai buvo tauta, kuri jau praėjo. Jai priklauso tai, ką ji užsidirbo, o jums priklauso tai, ką jūs užsidirbote. Ir jūs ne būsite klausiami apie tai, ką jie darė. 2:134; 2:141
- = Amžinai jie ten pasiliks; bausmė jiems nebus palengvinta, ir jie nebus atidėti. 2:162; 3:88
- = Išskyrus tuos, kurie po to atgailauja ir pasitaiso. Iš tiesų, Allahas yra Atleidžiantis, Gailestingasis. 3:89; 24:5
- = O tie, kurie netikėjo ir neigė Mūsų ženklus – tie yra Pragaro gyventojai. 5:10; 5:86
- = Ir neateina jiems joks ženklas iš jų Viešpaties ženklų, kad jie nuo jo nenusigręžtų. 6:4; 36:46
- = Ir jau iki tavęs buvo pašaipiami pasiuntiniai, bet tuos, kurie iš jų tyčiojosi, ištiko tai, iš ko jie tyčiojosi. 6:10; 21:41
- = Sakyk: "Aš bijau, jei nepaklusiu savo Viešpačiui, Didžiosios dienos bausmės." 6:15; 39:13
- = Ir žemės drebėjimas juos ištiko, ir jie liko savo namuose gulinčiais veidais žemyn. 7:78; 7:91
- = Ir jis metė savo lazdą, ir štai ji tapo akivaizdžia gyvate. 7:107; 26:32
- = Ir jis ištraukė savo ranką, ir štai ji pasidarė balta (spindinti) stebintiesiems. 7:108; 26:33
- = Jie tarė: "Mes tikime į pasaulių Viešpatį." 7:121; 26:47
- = Mozės ir Harūno Viešpatį. 7:122; 26:48
- = Ir Aš duosiu jiems atidėjimą. Iš tiesų, Mano planas yra tvirtas. 7:183; 68:45
- = Jis yra tas, kuris siuntė Savo Pasiuntinį su vedimu ir tiesos religija, kad ją iškeltų virš visų religijų, net jei daugdieviams tai nemalonu. 9:33; 61:9
- = O Pranašau, kovok prieš netikinčiuosius ir veidmainius ir būk jiems griežtas. Jų prieglobstis yra Pragaras, ir kokia baisi pabaiga! 9:73; 66:9
- = Ir jie sako: "Kada šis pažadas, jei esate teisingi?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Ir Mes siuntėme Mozę su Mūsų ženklais ir aiškia valdžia. 11:96; 40:23
- = Ir Mes davei Mozei Knygą, bet dėl jos kilo nesutarimų. Ir jei nebūtų buvęs žodis, pirmiau ištartas tavo Viešpaties, būtų tarp jų nuspręsta. Ir jie yra dėl jos abejonėje. 11:110; 41:45
- = Tai nėra sunku Allahui. 14:20; 35:17
- = "Ir kai Aš jį sutvarkysiu ir įpūsiu jam iš Savo dvasios, puolte prieš jį nusilenkdami." 15:29; 38:72
- = Ir angelai visi kartu nusilenkė. 15:30; 38:73
- = (Allahas) tarė: "Taigi išeik iš jo, nes tu esi išvytas." 15:34; 38:77
- = (Iblis) tarė: "Mano Viešpatie, duok man atidėjimą iki Dienos, kai jie bus prikelti." 15:36; 38:79
- = (Allahas) tarė: "Tu esi vienas iš tų, kuriems duotas atidėjimas." 15:37; 38:80
- = Iki nustatyto laiko dienos." 15:38; 38:81
- = Išskyrus Tavo išrinktus tarnus tarp jų. 15:40; 38:83
- = Iš tiesų, dievobaimingieji bus tarp sodų ir šaltinių. 15:45; 51:15
- = (Abrahamas) tarė: "Koks jūsų reikalas, o pasiuntiniai?" 15:57; 51:31
- = Jie tarė: "Mes esame siųsti pas nusidėjėlių tautą." 15:58; 51:32
- = Tie, kurie tikėjo ir nesumaišė savo tikėjimo su neteisybe – jiems priklauso saugumas, ir jie yra teisingai vedami. 16:42; 29:59
- = Kad jie būtų dėkingi už tai, ką Mes jiems davei. Mėgaukitės, bet jūs sužinosite. 16:55; 30:34
- = Paskui jis pasirinko kelią. 18:89; 18:92
- = Eik pas Faraoną, nes jis tikrai persistengė. 20:24; 79:17
- = Ir tie, kurie saugo savo lytinius organus. 23:5; 70:29
- = Išskyrus su savo žmonomis arba tomis, kurias valdo jų dešinės rankos – jie nėra kaltinami. 23:6; 70:30
- = O kas siekia daugiau nei tai, tie yra nusikaltėliai. 23:7; 70:31
- = Ir tie, kurie saugo jiems patikėtus daiktus ir savo pažadus. 23:8; 70:32
- = (Nojus) tarė: "Mano Viešpatie, padėk man, nes jie mane išvadino melagiu." 23:26; 23:39
- = Ta, Sin, Mim. 26:1; 28:1
- = Tai yra aiškios Knygos eilutės. 26:2; 28:2
- = Iš tiesų, tame yra ženklas, bet dauguma jų netikėjo. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = Ir iš tiesų, tavo Viešpats – Jis yra Galingasis, Gailestingasis. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = Ir Mes paskandinome kitus. 26:66; 37:82
- = Aš esu jums patikimas pasiuntinys. 26:107; 26:125; 26:143; 26:162; 26:178
- = Tad bijokite Allaho ir pakluskite man. 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = Ir aš neprašau iš jūsų už tai atlygio. Mano atlygis yra tik iš pasaulių Viešpaties. 26:109; 26:127; 26:145; 26:164; 26:180
- = Soduose ir prie šaltinių. 26:147; 44:52
- = Jie tarė: "Tu esi tik vienas iš užburtųjų." 26:153; 26:185
- = Išskyrus jo žmoną – Mes nusprendėme, kad ji bus tarp tų, kurie liks. 26:171; 37:135
- = Paskui Mes sunaikinome kitus. 26:172; 37:136
- = Ir Mes ant jų pylėme lietų (iš akmenų), ir koks baisus buvo lietus tiems, kurie buvo perspėti! 26:173; 27:58
- = Ar jie nori paskubinti bausmę? 26:204; 37:176
- = Tie, kurie atlieka maldą, duoda išmaldą ir tvirtai tiki pomirtiniu gyvenimu. 27:3; 31:4
- = Ir (prisimink) Dieną, kai Jis juos šauks ir sakys: "Kur mano 'talkininkai', kuriuos jūs tvirtinote?" 28:62; 28:74
- = Ir mūsų protėviai? 37:17; 56:48
- = Ir jie eis vienas prie kito, klausinėdami. 37:27; 52:25
- = Bet (jie) yra Allaho išrinkti tarnai. 37:40; 37:74; 37:128; 37:160
- = Palaimos soduose. 37:43; 56:12
- = Ir Mes palikome jam (gerą vardą) tarp vėlesnių kartų: 37:78; 37:108; 37:129
- = Iš tiesų, Mes taip atlyginame geradariams. 37:80; 37:121; 37:131; 77:44
- = Iš tiesų, jis buvo vienas iš Mūsų tikinčių tarnų. 37:81; 37:111; 37:132
- = Kas su jumis? Kaip jūs teisiate? 37:154; 68:36
- = Tai ne kas kita, kaip priminimas pasauliams. 38:87; 81:27
- = Knygos siuntimas yra nuo Allaho – Galingojo, Išmintingojo. 39:1; 45:2; 46:2
- = Ha, Mim. 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = Prisiekiu aiškiąja Knyga. 43:2; 44:2
- = Tad palik juos, tegul jie skęsta tuščiose kalbose ir žaidimuose, kol susidurs su savo Diena, kuri jiems pažadėta. 43:83; 70:42
- = (Jiems bus pasakyta): "Valgykite ir gerkite su malonumu už tai, ką darėte." 52:19; 77:43
- = O gal prašai iš jų atlygio, kad jie būtų slegiami skolų? 52:40; 68:46
- = O gal jie turi žinių apie paslėptą, ir jie tai užrašo? 52:41; 68:47
- = Ir kokia buvo Mano bausmė ir Mano perspėjimai! 54:16; 54:21; 54:30
- = Ir Mes padarėme Koraną lengvai įsimenamą. Ar yra kas nors, kas prisimintų? 54:17; 54:22; 54:32; 54:40
- = Tad kuriuos savo Viešpaties gėrybių neigsite? 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = Didelė grupė iš pirmųjų. 56:13; 56:39
- = Ir mes buvome (to) atimti? 56:67; 68:27
- = Tad šlovink savo Viešpaties, Didžiausio, vardą. 56:74; 56:96; 69:52
- = Tai siuntimas nuo pasaulių Viešpaties. 56:80; 69:43
- = Visa, kas yra danguose, ir visa, kas yra žemėje, šlovina Allahą, ir Jis yra Galingasis, Išmintingasis. 59:1; 61:1
- = Kai Mūsų eilutės jau skaitomos jam, jis sako: "Tai senovės žmonių padavimai!" 68:15; 83:13
- = Tad jis bus maloniame gyvenime. 69:21; 101:7
- = Aukštame sode. 69:22; 88:10
- = Ir jis neragina maitinti vargšo. 69:34; 107:3
- = Iš tiesų, tai (Koranas) yra kilnaus Pasiuntinio žodžiai. 69:40; 81:19
- = Iš tiesų, tai yra priminimas. Tad kas nori, tegul pasirenka kelią į savo Viešpatį. 73:19; 76:29
- = Tad kas nori, tegul jį prisimena. 74:55; 80:12
